public void testSimpleConversion_3_oe() throws Exception {
    final String[] message= {
        "from String",
        "from String",
        "from String",
        "from String",
        "from String",
        "from String",
        "from String",
        "from Byte",
        "from Short",
        "from Integer",
        "from Long",
        "from Float",
        "from Double"
    };

    final Object[] input = {
        String.valueOf(Long.MIN_VALUE),
        "-17",
        "-1",
        "0",
        "1",
        "17",
        String.valueOf(Long.MAX_VALUE),
        new Byte((byte)7),
        new Short((short)8),
        new Integer(9),
        new Long(10),
        new Float(11.1),
        new Double(12.2)
    };

    final Long[] expected = {
        new Long(Long.MIN_VALUE),
        new Long(-17),
        new Long(-1),
        new Long(0),
        new Long(1),
        new Long(17),
        new Long(Long.MAX_VALUE),
        new Long(7),
        new Long(8),
        new Long(9),
        new Long(10),
        new Long(11),
        new Long(12)
    };

    for(int i=0;i<expected.length;i++) {
        // removed other assertion
        // removed other assertion
        assertEquals(message[i] + " to null type",expected[i],converter.convert(null,input[i]));
}
}

